import pathlib,json,gzip,hashlib,csv
R=pathlib.Path(__file__).resolve().parents[1];source=R/'raw/sse-margin-gap-20211213-api.json';d=json.loads(source.read_text());rows=d['result'];total=d['pageHelp']['total'];assert len(rows)==total and d['pageHelp']['pageCount']==1 and {x['opDate'] for x in rows}=={'20211213'} and len({x['stockCode'] for x in rows})==len(rows)
